class BankAccount
  attr_reader :balance
  def initialize; @balance = 0; end
  def deposit(cents)
    raise ArgumentError unless cents.is_a?(Integer) && cents > 0
    @balance += cents
  end
  def withdraw(cents)
    raise ArgumentError unless cents.is_a?(Integer) && cents > 0
    raise "Insufficient funds" if cents > @balance
    @balance -= cents
  end
end

